  "hbr.fontsGuide.eyebrow": "Hotel Barcelona · Шрифти",
  "hbr.fontsGuide.title": "Як додати українські літери у шрифти HBR",
  "hbr.fontsGuide.subtitle": "Після розпакування шрифтів потрібно згенерувати нові гліфи через TMPUnity.exe і покласти їх назад у теки MonoBehaviour / Atlas. Нижче — повний цикл.",
  "hbr.fontsGuide.ok": "Зрозуміло",
  "hbr.fontsGuide.prev": "Назад",
  "hbr.fontsGuide.next": "Далі",
  "hbr.fontsGuide.footerHint": "Цю інструкцію можна відкрити знов кнопкою «Інструкція» у Кроці 3.",
  "hbr.fontsGuide.tipTitle": "Перед заміною — резервна копія",
  "hbr.fontsGuide.tipBody": "Зробіть резервну копію цих тек, щоб швидко відкотитись, якщо щось піде не так:",

  "hbr.fontsGuide.c1.title": "Крок 1. Запустіть TMPUnity і завантажте дамп",
  "hbr.fontsGuide.c1.body": "Відкрийте TMPUnity.exe, увімкніть чекбокс «Завантажити символи з дампу» і відкрийте будь-який .json з нашої теки MonoBehaviour. Далі вкажіть ваш .ttf-шрифт із новими гліфами.",
  "hbr.fontsGuide.c2.title": "Крок 2. Додайте літери і згенеруйте",
  "hbr.fontsGuide.c2.body": "У список символів додайте українські літери, яких бракує у грі, і натисніть «Згенерувати шрифт». Зачекайте, поки генерація завершиться.",
  "hbr.fontsGuide.c3.title": "Крок 3. Збережіть у окрему теку",
  "hbr.fontsGuide.c3.body": "Натисніть «Пропатчити та зберегти». КРИТИЧНО важливо вибрати ОКРЕМУ теку для виводу (наприклад «dump»), а НЕ оригінальні MonoBehaviour/Atlas. Створіть її в Провіднику самостійно.",
  "hbr.fontsGuide.c3.note": "Якщо збережете напряму в MonoBehaviour/Atlas — затрете оригінали і втратите можливість безболісно перетягати по одному файлу.",
  "hbr.fontsGuide.c4.title": "Крок 4. Замініть MonoBehaviour і Atlas",
  "hbr.fontsGuide.c4.body": "З теки «dump» скопіюйте з заміною новий .json у MonoBehaviour. Потім перейменуйте новий .png так, як називається оригінал у теці Atlas (повна назва — з префіксом «… Atlas-CAB-…»), і теж скопіюйте з заміною.",
  "hbr.fontsGuide.c5.title": "Крок 5. Запакуйте у гру",
  "hbr.fontsGuide.c5.body": "Поверніться у цю програму і натисніть «Запакувати у гру» в Кроці 4. Нові символи з'являться у Hotel Barcelona.",
  "hbr.fontsGuide.c5.note": "Перед заміною файлів зробіть резервну копію тек MonoBehaviour і Atlas — щоб швидко відкотитись, якщо щось піде не так.",

  "hbr.fontsGuide.s1.title.deprecated": "Крок 1. Запустіть генератор шрифтів",
  "hbr.fontsGuide.s1.body": "Відкрийте програму TMPUnity.exe (її ми вже завантажили на Кроці 1):",
  "hbr.fontsGuide.s2.title": "Крок 2. Завантажте символи з дампу",
  "hbr.fontsGuide.s2.body": "У вікні TMPUnity увімкніть чекбокс «Завантажити символи з дампу». Потім відкрийте будь-який .json-дамп з нашої теки MonoBehaviour (приклад нижче):",
  "hbr.fontsGuide.s3.title": "Крок 3. Виберіть зовнішній шрифт",
  "hbr.fontsGuide.s3.body": "Після відкриття .json-дампу вкажіть зовнішній .ttf-шрифт, з якого додаватимуться нові символи у ігровий шрифт.",
  "hbr.fontsGuide.s4.title": "Крок 4. Додайте потрібні символи",
  "hbr.fontsGuide.s4.body": "У список символів додайте українські літери, яких бракує у грі. Далі натисніть «Згенерувати шрифт».",
  "hbr.fontsGuide.s5.title": "Крок 5. Пропатчіть і збережіть шрифт",
  "hbr.fontsGuide.s5.body": "Дочекайтесь завершення генерації, потім натисніть «Пропатчити та зберегти». Створіть ОКРЕМУ теку (наприклад, dump) для результату:",
  "hbr.fontsGuide.s5.note": "Не зберігайте файли напряму у наші теки MonoBehaviour або Atlas — спочатку у свою окрему «dump»-теку, далі вручну замінюємо.",
  "hbr.fontsGuide.s6.title": "Крок 6. Замініть MonoBehaviour-файл",
  "hbr.fontsGuide.s6.body": "У створеній «dump»-теці знайдіть оновлений .json (з такою ж назвою як оригінал) і скопіюйте його з заміною у нашу теку MonoBehaviour:",
  "hbr.fontsGuide.s7.title": "Крок 7. Скопіюйте назву атласу",
  "hbr.fontsGuide.s7.body": "У нашій теці Atlas знайдіть текстуру атласу того ж шрифту і скопіюйте її повну назву файла (вона потрібна для наступного кроку):",
  "hbr.fontsGuide.s8.title": "Крок 8. Замініть Atlas-файл",
  "hbr.fontsGuide.s8.body": "У «dump»-теці знайдіть згенерований .png-атлас і перейменуйте його точно як оригінал з нашої теки Atlas. Потім скопіюйте з заміною:",
  "hbr.fontsGuide.s9.title": "Крок 9. Запакуйте нові шрифти",
  "hbr.fontsGuide.s9.body": "Поверніться у цю програму і натисніть «Запакувати у гру». Нові символи з'являться у Hotel Barcelona.",
  "hbr.fonts.cachedSummary": "Вже розпаковано раніше · {atlas} атласів і {mono} TMP_FontAsset знайдено на диску.",
  "hbr.fonts.step3Title": "Крок 3. Згенерувати нові шрифти у TMPUnity",
  "hbr.fonts.step3Body": "Для генерації нових шрифтів необхідно відкрити TMPUnity.exe. Замінюй у ньому ті самі файли з тек HBR\\Fonts\\Atlas\\ та HBR\\Fonts\\MonoBehaviour\\ — пізніше програма запакує їх назад у гру.",
  "hbr.fonts.launchTmpUnity": "Відкрити TMPUnity.exe",
  "hbr.fonts.step4Title": "Крок 4. Запакувати назад у гру",
  "hbr.fonts.step4Subtitle": "Після того як TMPUnity перезаписав файли у твоїх теках, пакуємо їх назад у bundle (той самий, де лежить текст). Перед записом створиться резервна копія `.bundle.fonts.bak`.",
  "hbr.fonts.packBtn": "Запакувати у гру",
