  "hbr.fontsGuide.openHint": "Step-by-step guide on how to work with TMPUnity and inject new glyphs.",
  "hbr.fontsGuide.eyebrow": "Hotel Barcelona · Fonts",
  "hbr.fontsGuide.title": "How to add Ukrainian glyphs to HBR fonts",
  "hbr.fontsGuide.subtitle": "Once fonts are unpacked, you generate new glyphs in TMPUnity.exe and drop them back into the MonoBehaviour / Atlas folders. Full cycle below.",
  "hbr.fontsGuide.ok": "Got it",
  "hbr.fontsGuide.prev": "Back",
  "hbr.fontsGuide.next": "Next",
  "hbr.fontsGuide.footerHint": "You can reopen this guide later via the “Guide” button in Step 3.",
  "hbr.fontsGuide.tipTitle": "Back up before replacing",
  "hbr.fontsGuide.tipBody": "Make a copy of these folders so you can roll back quickly if something goes wrong:",

  "hbr.fontsGuide.c1.title": "Step 1. Launch TMPUnity and load the dump",
  "hbr.fontsGuide.c1.body": "Open TMPUnity.exe, enable the “Load characters from dump” checkbox, then open any .json from our MonoBehaviour folder. After that, pick your .ttf font with the new glyphs.",
  "hbr.fontsGuide.c2.title": "Step 2. Add the letters and generate",
  "hbr.fontsGuide.c2.body": "Add the missing Ukrainian letters to the character list, then click “Generate font”. Wait for generation to finish.",
  "hbr.fontsGuide.c3.title": "Step 3. Save into a separate folder",
  "hbr.fontsGuide.c3.body": "Click “Patch and save”. It is CRITICAL to pick a separate output folder (e.g. “dump”) — NOT the original MonoBehaviour/Atlas. Create it manually in Explorer.",
  "hbr.fontsGuide.c3.note": "Saving directly into MonoBehaviour/Atlas overwrites originals and removes the ability to swap files one by one with confidence.",
  "hbr.fontsGuide.c4.title": "Step 4. Replace MonoBehaviour and Atlas",
  "hbr.fontsGuide.c4.body": "From the “dump” folder copy the new .json into MonoBehaviour with replace. Then rename the new .png to match the original Atlas filename (full name with “… Atlas-CAB-…” prefix) and copy with replace too.",
  "hbr.fontsGuide.c5.title": "Step 5. Pack into the game",
  "hbr.fontsGuide.c5.body": "Come back to this app and hit “Pack into the game” in Step 4. The new glyphs will show up in Hotel Barcelona.",
  "hbr.fontsGuide.c5.note": "Before replacing files, back up the MonoBehaviour and Atlas folders — so you can roll back quickly if something goes wrong.",

  "hbr.fontsGuide.s1.title.deprecated": "Step 1. Launch the font generator",
  "hbr.fontsGuide.s1.body": "Open TMPUnity.exe (we already downloaded it back in Step 1 of this screen):",
  "hbr.fontsGuide.s2.title": "Step 2. Load characters from the dump",
  "hbr.fontsGuide.s2.body": "In TMPUnity, enable the “Load characters from dump” checkbox. Then open any .json dump from our MonoBehaviour folder (example below):",
  "hbr.fontsGuide.s3.title": "Step 3. Pick an external font",
  "hbr.fontsGuide.s3.body": "After opening the .json dump, select an external .ttf font that contains the new glyphs you want to inject.",
  "hbr.fontsGuide.s4.title": "Step 4. Add the required characters",
  "hbr.fontsGuide.s4.body": "Add the Ukrainian letters the game is missing. Then click “Generate font”.",
  "hbr.fontsGuide.s5.title": "Step 5. Patch and save the font",
  "hbr.fontsGuide.s5.body": "Wait until generation finishes, then click “Patch and save”. Pick a SEPARATE output folder (e.g. dump):",
  "hbr.fontsGuide.s5.note": "Don’t save directly into our MonoBehaviour / Atlas folders — put the result into a separate “dump” folder first, then copy with replace manually.",
  "hbr.fontsGuide.s6.title": "Step 6. Replace the MonoBehaviour file",
  "hbr.fontsGuide.s6.body": "In the “dump” folder find the updated .json (same name as the original) and copy it with replace into our MonoBehaviour folder:",
  "hbr.fontsGuide.s7.title": "Step 7. Copy the atlas filename",
  "hbr.fontsGuide.s7.body": "Go to our Atlas folder, find the atlas texture of the same font, copy its full filename (you’ll need it for the next step):",
  "hbr.fontsGuide.s8.title": "Step 8. Replace the Atlas file",
  "hbr.fontsGuide.s8.body": "In your “dump” folder rename the generated .png to match the original Atlas filename, then copy with replace:",
  "hbr.fontsGuide.s9.title": "Step 9. Pack the updated fonts",
  "hbr.fontsGuide.s9.body": "Come back to this app and hit “Pack into the game”. The new glyphs will show up in Hotel Barcelona.",
