/** Localize a raw backend (main-process) error string. Unknown strings pass through. */
export function localizeBackendError(msg?: string | null): string {
  if (!msg) return "";
  for (const e of BACKEND_ERRORS) {
    if (e.prefix) {
      if (msg.startsWith(e.m)) return t(e.key) + msg.slice(e.m.length);
    } else if (msg === e.m) {
      return t(e.key);
    }
  }
  return msg;
}

/** React hook: повертає актуальну `t` і ре-рендерить компонент при зміні мови. */
export function useT(): typeof t {
  const [, force] = useState(0);
  useEffect(() => {
    const cb = () => force((x) => x + 1);
    listeners.add(cb);
    return () => { listeners.delete(cb); };
  }, []);
  return t;
}
